import { useCallback } from 'react';
import { PIN_CONSTANTS } from '~/entities/pin/lib/constants';
import { closeWebview } from '~/shared/api/web-view';
import i18n from '~/shared/i18n/i18n';
import { PATHS } from '~/shared/routes/paths';
import { useAlertDialog } from './use-alert-dialog';
import { useNavigate } from './use-navigate';

export const useMaxFailureHandler = () => {
  const { openAlertDialog } = useAlertDialog();
  const { navigate } = useNavigate();

  const handleMaxFailure = useCallback(
    (state?: Record<string, any>) => {
      openAlertDialog({
        message: i18n.t('pin:errorMaxPin'),
        onConfirmClick: () => {
          setTimeout(() => {
            const destination = window.opener
              ? closeWebview({ redirectPath: PATHS.pwFail })
              : navigate(PATHS.pwFail, {
                  state: { ...(state || {}), type: 'AUTH_FAIL' },
                  replace: true,
                });
          }, PIN_CONSTANTS.NAVIGATION_DELAY);
        },
      });
    },
    [openAlertDialog, navigate],
  );

  return { handleMaxFailure };
};
