import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { useStore } from '~/app/store/store';
import { ConfirmUserResponse } from '~/entities/pin/api/dtos/types';
import { UserParams } from '~/entities/user/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { KickOutError } from '~/shared/lib/utils/error';
import { resultify } from '~/shared/lib/utils/resultify';

type ConfirmUserRequest = Partial<UserParams> & {
  account?: string;
};

const getConfirmUser = (tbCstmrMastr: ConfirmUserRequest) => {
  if (!tbCstmrMastr.cstmrNo) {
    throw new KickOutError('cstmrNo is required');
  }

  const { account, ...restTbCstmrMastr } = tbCstmrMastr;
  const confirmUserPayload = {
    tbCstmrMastr: {
      ...restTbCstmrMastr,
      ...(account !== undefined ? { acnutno: account } : {}),
    },
  };

  //{result : [0 ,1, 2, 3] [회원미가입, 생체로그인, 간편로그인, 디바이스불일치], failrCo : 로그인 실패 건수 }
  return resultify(axios.post<ConfirmUserResponse>(`${API_URLS.realConfirmUser}`, confirmUserPayload));
};

export const useGetConfirmUserMutation = (
  options?: MutationOptions<ConfirmUserRequest, CBDCAxiosError, ConfirmUserResponse>,
) => {
  const setIncorrectPinCount = useStore.getState().pinSlice.setIncorrectPinCount;
  const mutation = useMutation<ConfirmUserResponse, CBDCAxiosError, ConfirmUserRequest>({
    ...options,
    mutationFn: (tbCstmrMastr: ConfirmUserRequest) => getConfirmUser(tbCstmrMastr),
    onSuccess: (data) => {
      const { failrCo } = data;
      setIncorrectPinCount(failrCo);
    },
  });

  return {
    ...mutation,
  };
};
